\subsection{Deriving the Unified Preference Objective} 


% \begin{align}
% \arg \max_\theta L_\Psi(\phi) + \mathbb{E}_{x \sim \mathcal{D}, y \sim \pi_\phi(\cdot \mid x)}[\alpha_R R(x, y)]
% \end{align}

\arg \max_\phi \mathbb{E}_{x \sim \mathcal{D}, y \sim \pi_\phi(\cdot \mid x)}[r_p(x, y) + \alpha A_\theta(x, y)] - \beta D_{\mathrm{KL}}(\pi_\phi || \pi_{\mathrm{ref}})
\label{eqn:modrlhf}
\end{align}
Based on \citet{rafailov2024direct}, we can obtain an analytical solution for \autoref{eqn:modrlhf} in terms of the partition function $Z(x)$ and the optimal policy to maximize only the auxiliary objective $\alpha A_\theta(x, y)$, $\pi^*_r$ (\autoref{eqn:optim}). \begin{align}
    \pi^*(y \mid x) &= \frac{1}{Z(x)} \pi_\mathrm{ref}(y \mid x) \exp(\frac{1}{\beta}  (r_p(x, y) + \alpha A_\theta(x, y)) ) \nonumber   
 \\
 &\propto \underbrace{\pi_\mathrm{ref}(y \mid x) \exp(\frac{\alpha}{\beta}  A_\theta(x, y) )}_{\text{optimal auxiliary policy } \pi_r^*} \exp(\frac{1}{\beta}r_p(x, y)) \propto \pi^*_r(y \mid x) \exp(\frac{1}{\beta}r_p(x, y))  \label{eqn:optim}

\end{align} We rearrange the preference reward $r_p$ in terms of the optimal policy, reference policy, and advantage function. \begin{align}
r_p(x, y) = \beta (\log \frac{\pi^*(y \mid x)}{\pi_{\mathrm{ref}}(y \mid x)} + \log Z(x)) - \alpha A_\theta(x, y)
\end{align} Since the advantage function $A_\theta$ is computable, we can reformulate the preference reward using any chosen preference model, e.g., Bradley-Terry, as maximum likelihood objectives. In these cases, the value function and partition function terms cancel and we arrive at a similar optimization problem as in \citet{rafailov2024direct} or \citet{zhou2023beyond}. For completeness, we include a derivation using the Bradley-Terry preference model \citep{bradley1952rank} in  \aref{app:deriv}, and a similar derivation is applicable for others such as Plackett-Luce \citep{plackett1975analysis} or Kahnemann-Tversky \citep{kahneman1979prospect}. For maximum generality, we assume that preference reward optimization is conducted using a generic OPT objective $L_\Psi(\phi)$---such as DPO, KTO, etc.---which, when maximized, optimizes the preference reward $r_p$.

% \begin{align}
% \arg \max_\theta L_\Psi(\phi) + \mathbb{E}_{x \sim \mathcal{D}, y \sim \pi_\phi(\cdot \mid x)}[\alpha_R R(x, y)]
% \end{align}

% \begin{align}
% \arg \max_\theta L_\Psi(\phi) + \mathbb{E}_{x \sim \mathcal{D}, y \sim \pi_\phi(\cdot \mid x)}[\alpha_R R(x, y)]
% \end{align}

\label{eqn:almostfinal}
\end{align} Using the known definition of $\pi^*_r$, we can simplify \autoref{eqn:almostfinal} and drop its partition term since it is a constant with respect to the optimization variable $\phi$. This amounts to a weighted maximum likelihood loss to optimize the auxiliary objectives, $L_\pi(\phi) = \mathbb{E}_{x \sim \mathcal{D}}[ \log \pi_\phi(y | x) \exp(\frac{\alpha}{\beta} A_\theta(x, y))]$, as shown in \autoref{eqn:final}.
\begin{align}
=&\arg \max_\phi L_\Psi(\phi) + \gamma \mathbb{E}_{x \sim \mathcal{D}}[\sum_y \pi_\mathrm{ref}(y|x) \exp(\frac{\alpha}{\beta}  A_\theta(x, y)) \log \pi_\phi(y \mid x)] \nonumber \\
=&\arg \max_\phi L_\Psi(\phi) + \gamma \mathbb{E}_{(x, y) \sim \mathcal{D}}[ \log \pi_\phi(y \mid x) \exp(\frac{\alpha}{\beta} A_\theta(x, y))] \nonumber \\
=&\arg \max_\phi \underbrace{L_\Psi(\phi)}_{\text{preference objective}} + \underbrace{\gamma L_\pi(\phi)}_{\text{auxiliary objective(s)}}
\label{eqn:final}

\label{eqn:final}
\end{align}
To train the value network $V_\theta(x)$ for advantage estimation, we leverage expectile regression on the auxiliary rewards (\autoref{eqn:expectile}), following the offline RL technique proposed in \citet{kostrikov2021offline}.
\begin{align}
    L_V(\theta) = \mathbb{E}_{(x, y) \sim \mathcal{D}} [L_2^\tau(R(x, y) - V_\theta(x))]
    \label{eqn:expectile}
\end{align}

