\subsubsection{Can UPO ignore noisy or random rewards?}

\revised{Consider a scenario in which we add a significant number of auxiliary objectives, such that the overall auxiliary reward becomes noisy or even fully random. In that worst case where the overall reward is fully random, we examine with what happens to the generation capabilities of UPO. For simplicity, we perform this analysis with only LLAMA-13B, which has the best overall generative capabilities of the models tested.}

\subsubsection{Can UPO ignore noisy or random rewards?}

\revised{Consider a scenario in which we add a significant number of auxiliary objectives, such that the overall auxiliary reward becomes noisy or even fully random. In that worst case where the overall reward is fully random, we examine with what happens to the generation capabilities of UPO. For simplicity, we perform this analysis with only LLAMA-13B, which has the best overall generative capabilities of the models tested.}

\revised{Rather than simulating or adding many objectives, we simply add a random overall objective which signifies the combination of too many noisy objectives. Specifically, we use the formulation for $R(x, y)$ shown below, where $\mathrm{uniform}(z_0, z_1)$ provides a single uniformly random sample in the interval $[z_0, z_1]$ for $z_0, z_1 \in \mathbb{R}$.}
\begin{align}
    R(x, y) = \mathrm{uniform}(0, 1)
\end{align}
%
%
\revised{To ensure fairness in comparison, we use the same hyperparameters and dataset configuration as prior experiments (e.g., $\gamma$ or $\beta$). Since we do not use any actual auxiliary objectives (except for random) and hence are not concerned about auxiliary objective evaluation, we only present results for the overall GPT-4 evaluation.}

\revised{As presented in \autoref{tab:ablaterandom}, we clearly demonstrate that the evaluation with random auxiliary reward does not reduce the overall generation quality. In fact, it is slightly better on average than with the safety and readability objectives, though well within the margin of error. To examine why, we derive the advantage function under this random reward and the loss function.}
%
\begin{align}
    \mathbb{E}_{(x, y) \sim \mathcal{D}, R(x, y) \sim \mathrm{uniform}(0, 1)} \Big[ A(x, y)\Big] = \mathbb{E}_{(x, y) \sim \mathcal{D}, R(x, y) \sim \mathrm{uniform}(0, 1)} \Big[ R(x, y) - V_\theta(x)\Big]
\end{align}
%
\begin{wraptable}{r}{7.5cm} \vspace{-1em}
  % "r" for right, "5cm" for the width of the wrapping area  
  \centering  
  \caption{\revised{Evaluation metrics for UPO using a random auxiliary reward compared to baselines.}}  {\scriptsize
  \begin{tabular}{c || c}  
    \toprule  
    \bfseries \revised{Model} & \bfseries \revised{GPT-4 Win Percentage $\uparrow$}  \\  
    \midrule

\toprule  
    \bfseries \revised{Model} & \bfseries \revised{GPT-4 Win Percentage $\uparrow$}  \\  
    \midrule 
    \revised{DPO} & \revised{36.1 $\pm$ 4.3}  \\
    \revised{oPPO} & \revised{47.3 $\pm$ 4.3} \\
    \revised{MODPO} & \revised{38.8 $\pm$ 4.2} \\
    \revised{DRO-V} & \revised{43.9 $\pm$ 4.4} \\
    \revised{UPO\textsubscript{KTO}} & \revised{44.8 $\pm$ 4.3} \\
    \revised{UPO\textsubscript{DPO}} & {\revised{45.1 $\pm$ 4.4} } \\
    \revised{UPO\textsubscript{KTO} (random aux)} & \textbf{\revised{47.4 $\pm$ 4.4} } \\
    \bottomrule  
  \end{tabular}  
